// Shared value wrappers between the YAML loader and dumper.
//
// JavaScript's primitive types lose distinctions that PyYAML keeps after
// resolving a scalar (int vs float, string vs timestamp). The loader wraps
// those scalars in the classes below so the dumper can reproduce PyYAML's
// exact output.
//
// Value model produced by safeLoad() and consumed by safeDump():
//   - string        -> YAML str
//   - number (int)  -> YAML int
//   - boolean       -> YAML bool
//   - null          -> YAML null
//   - Array         -> YAML sequence
//   - plain Object  -> YAML mapping (keys are strings)
//   - YFloat        -> YAML float
//   - YTimestamp    -> YAML timestamp (date / datetime)

export class YFloat {
  // value: a JS number. May be Infinity, -Infinity or NaN.
  constructor(value) {
    this.value = value;
  }
}

export class YTimestamp {
  // text: the exact string PyYAML would emit for this timestamp
  // (e.g. "2020-01-01", "2001-12-15 02:59:43.1").
  constructor(text) {
    this.text = text;
  }
}
